// Generated by the /gstack-ship test coverage audit (pass 1).
// Value: protects=an image source is read as a local file, kept as data, or refused, never a remote or other-computer file; fails_when=a scheme, host or query rule in classifySource is loosened or dropped; why_new=images.spec.ts reaches classifySource only through embedImages and never with localhost, //host, query or %20; seam=none; no_claim=what the host does with a path (a fake host stands in for it; not exercised here)
import { expect, test } from 'vitest'

import { classifySource } from './images'

test('an image source is a local file only when it names one on this Mac; the web, other computers and look-alike schemes are refused', () => {
  // Arrange
  const pagesDir = '/r/pages'
  const sources = [
    'file://localhost/Users/u/a.png',
    'FILE:///Users/u/my%20shot.png',
    '/Users/u/a.png?x=1',
    'shot.png?v=2#top',
    'img/%E7%94%BB%E9%9D%A2.png',
    '../assets/a.png',
    '//cdn.test/a.png',
    'C:/Users/u/a.png',
    'data:text/html,<p>x</p>',
    'data:IMAGE/png;base64,AA==',
  ]

  // Act
  const classified = sources.map((source) => classifySource(source, pagesDir))

  // Assert
  expect(classified).toEqual([
    { kind: 'file', path: '/Users/u/a.png' },
    { kind: 'file', path: '/Users/u/my shot.png' },
    { kind: 'file', path: '/Users/u/a.png' },
    { kind: 'file', path: '/r/pages/shot.png' },
    { kind: 'file', path: '/r/pages/img/画面.png' },
    { kind: 'file', path: '/r/assets/a.png' },
    { kind: 'refused', reason: 'is not a local file' },
    { kind: 'refused', reason: 'is not a local file' },
    { kind: 'refused', reason: 'is not a local file' },
    { kind: 'embedded' },
  ])
})
